ign=amazon-mcf-support-button-2023-12-07','actioned','',NULL,NULL),(6533,49,'view_docs','Learn about Deposit schedules','https://woocommerce.com/document/woopayments/deposits/deposit-schedule/?utm_source=inbox_note&utm_medium=product&utm_campaign=view_docs#available-funds','unactioned','',NULL,NULL),(6534,50,'sirt-woo-2024-11-xss-admin','See available updates','https://woocommerce-1174581-6265451.cloudwaysapps.com/wp-admin/update-core.php?','unactioned','',NULL,NULL),(6535,50,'sirt-woo-2024-11-xss-admin','Dismiss','#','actioned','',NULL,NULL),(6536,51,'paypal-braintree-sdk-depreciation-2025-02-20-button','Upgrade now','https://woocommerce-1174581-6265451.cloudwaysapps.com/wp-admin/wp-admin/plugins.php','actioned','',NULL,NULL),(6537,52,'uk-vat-notice-button-2025-04-30','Learn more about this extension','https://wordpress.org/plugins/eu-vat-for-woocommerce/','actioned','',NULL,NULL),(6538,53,'paypal-braintree-sdk-depreciation-2025-05-30-button','Update now','https://woocommerce-1174581-6265451.cloudwaysapps.com/wp-admin/wp-admin/plugins.php','unactioned','',NULL,NULL),(6539,76,'woo-dotcom-course-2026-06-09','Visit the course','https://wordpress.com/support/courses/build-your-store-with-woocommerce/','actioned','',NULL,NULL);
